lines=['<?xml version="1.0" encoding="UTF-8"?>','<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">']
for u in urls:
    freq='weekly' if u in ['/','/mulch-calculator','/gravel-calculator'] else 'monthly'
    lines.append(f'<url><loc>{base}{u}</loc><lastmod>2026-09-29</lastmod><changefreq>{freq}</changefreq><priority>{pri.get(u,"0.7")}</priority></url>')
lines.append('</urlset>');(root/'sitemap.xml').write_text('\n'.join(lines)+'\n',encoding='utf-8')

(root/'SEO-CONTENT-REPORT-v2.5.md').write_text(f'''# MaterialYardage v2.5 — SEO / Content Expansion\n\nDate: 2026-09-29\n\n## New guides\n- /guides/topsoil-depth-guide\n- /guides/mulch-depth-guide\n- /guides/gravel-driveway-guide\n- /guides/concrete-calculator-guide\n- /guides/paver-calculator-guide\n\n## New reference resources\n- /reference/material-density-chart\n- /reference/conversion-tables\n- /reference/coverage-tables\n\n## Sitewide improvements\n- Guides and Reference links added to primary and footer navigation.\n- Calculator directory expanded with editorial guides and reference tables.\n- Topsoil page linked to its new depth guide and density reference.\n- Sitemap rebuilt using clean URLs.\n- New editorial pages include Article and FAQ structured data.\n- New pages are designed to provide formulas, examples, assumptions and limitations rather than thin keyword content.\n\nSitemap URL count: {len(urls)}\n''',encoding='utf-8')
print('created',len(pages),'new pages; sitemap',len(urls))
